// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address actor, uint128 amount, uint48 unlockTime) public {
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        vm.assume(amount > 0);

        // Record initial state
        uint256 initBal = address(c).balance;
        uint256 initAccBal = c.Acc(actor).balance;

        // Fund the actor and call Put
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(uint256(unlockTime));

        // Observe actual balance changes
        uint256 finalBal = address(c).balance;
        uint256 finalAccBal = c.Acc(actor).balance;

        // General invariant: the increase in this account's internal balance must equal the ETH received from this Put
        // (which is exactly the increase in contract ETH balance, since it receives only this tx's value)
        assertTrue(finalAccBal - initAccBal == finalBal - initBal);
    }
}

