pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 count) public {
        // count: number of Put calls to perform; keep it within a reasonable range
        count = bound(count, 0, 20);
        // Use a deterministic actor to avoid needing to track multiple addresses
        address actor = address(0x1234);
        uint256 totalDeposited = 0;

        for (uint256 i = 0; i < count; i++) {
            // Fuzz the deposit amount and unlock time for each call
            uint256 amount = bound(uint256(keccak256(abi.encode(i, count, "amount"))), 0, 1000 ether);
            uint256 unlockTime = bound(uint256(keccak256(abi.encode(i, count, "unlock"))), 0, type(uint256).max - 1);
            vm.deal(actor, amount);
            vm.prank(actor);
            c.Put{value: amount}(unlockTime);
            totalDeposited += amount;
        }

        uint256 accBalance = c.Acc(actor).balance;
        // The rule: for the single actor used, their acc.balance must equal the total ETH they sent
        // The bug adds an extra wei per Put, so accBalance will be totalDeposited + count instead of totalDeposited
        // and the contract's ETH balance will be totalDeposited, causing a mismatch.
        // More generally, address(c).balance >= sum of all acc.balance entries always holds for the reference,
        // but the bug makes accBalance > address(c).balance.
        assertTrue(accBalance == address(c).balance);
    }
}

