pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint8 putCalls) public {
        // 1. Restrict to admissible domain: amounts must be <= a safe upper bound to avoid overflow in summation,
        //    and putCalls must be >= 1 so we actually perform at least one Put.
        bound(amount1, 0, 1e30);
        bound(amount2, 0, 1e30);
        vm.assume(putCalls >= 1 && putCalls <= 100);
        // 2. Deploy fresh c and two distinct actors.
        address actor1 = address(0x10000);
        address actor2 = address(0x20000);
        vm.deal(actor1, amount1 * putCalls + 1 ether);
        vm.deal(actor2, amount2 * putCalls + 1 ether);
        // 3. Track the total msg.value sent by both actors across all Put calls.
        uint256 totalDeposited = 0;
        for (uint8 i = 0; i < putCalls; i++) {
            vm.prank(actor1);
            c.Put{value: amount1}(block.timestamp + 100);
            totalDeposited += amount1;
            vm.prank(actor2);
            c.Put{value: amount2}(block.timestamp + 100);
            totalDeposited += amount2;
        }
        // 4. Assert: sum of internal balances equals total deposited value.
        uint256 sumBalances = c.Acc(actor1) + c.Acc(actor2);
        assertTrue(sumBalances == totalDeposited);
    }
}

