import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 unlockTimeArg) public {
        address user = address(0x1234);
        // Restrict domain to admissible ranges: deposit >= collect, positive amounts, etc.
        vm.assume(depositAmount > 0 && depositAmount < type(uint128).max);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);
        vm.assume(unlockTimeArg > block.timestamp); // reference sets future unlockTime, bug sets past
        // Ensure contract has minimum sum requirement
        vm.assume(depositAmount >= c.MinSum());
        collectAmount = bound(collectAmount, 1, depositAmount);
        // Setup user with Ether
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Put{value: depositAmount}(unlockTimeArg);
        // Immediately try to collect: reference should revert because unlockTime is in the future;
        // buggy version set unlockTime to block.timestamp - 1, allowing immediate collection.
        bool ok;
        vm.prank(user);
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }
        // Assert that the reference's behavior (revert) holds for all admissible inputs:
        // the collect call must revert because unlockTime > block.timestamp.
        assertTrue(!ok);
    }
}

