pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint128 depositAmount, uint128 withdrawAmount, address attacker) public {
        // 1. Domain restrictions: amounts must be >0, withdraw <= deposit, attacker cannot be this or zero address
        vm.assume(attacker != address(this) && attacker != address(0) && attacker.code.length == 0);
        depositAmount = uint128(bound(depositAmount, 1, type(uint128).max));
        withdrawAmount = uint128(bound(withdrawAmount, 1, depositAmount));
        unlockTime = bound(unlockTime, 1, type(uint128).max);

        // 2. Deploy adversarial re-entrant attacker
        ReentrantAttacker re = new ReentrantAttacker(c, withdrawAmount);
        address(re).call{value: 0}(''); // force deploy
        vm.deal(address(re), depositAmount);

        // 3. Attacker puts deposit via fallback (locked_ is true after require, but not set in buggy version)
        vm.prank(address(re));
        c.fallback{value: depositAmount}();

        // 4. Warp past unlock time so Collect can proceed
        vm.warp(unlockTime + 1);

        // 5. Collect triggers re-entrancy; bug allows re-entrant Put during collect
        vm.prank(address(re));
        try c.Collect(withdrawAmount) { } catch { }

        // 6. Assert that attacker balance never decreased below depositAmount - withdrawAmount (reference holds, bug may decrease more)
        ( , uint256 finalBalance) = c.Acc(address(re));
        assertTrue(finalBalance >= depositAmount - withdrawAmount);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 amt;
    bool reentered;

    constructor(C _target, uint256 _amt) payable {
        target = _target;
        amt = _amt;
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-entrant Put via fallback using the Ether we just received from Collect
            target.fallback{value: msg.value}();
        }
    }
}

