import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialDeposit, uint256 collectAmount, uint256 attackerInitialBalance) public {
        // Bound amounts to reasonable ranges that allow reentrancy attack
        initialDeposit = bound(initialDeposit, 1 ether, 10 ether);
        collectAmount = bound(collectAmount, 1 ether, initialDeposit);
        attackerInitialBalance = bound(attackerInitialBalance, 1 ether, 5 ether);

        // Deploy reentrant attacker
        ReentrantAttacker attacker = new ReentrantAttacker(c, collectAmount);
        address attackerAddr = address(attacker);

        // Fund attacker and deploy as msg.sender
        vm.deal(attackerAddr, attackerInitialBalance);
        vm.prank(attackerAddr);
        c.Put{value: initialDeposit}(block.timestamp + 1000);

        // Warp past unlock time
        vm.warp(block.timestamp + 2000);

        // Record balance before collect
        (uint unlockTime, uint balanceBefore) = c.Acc(attackerAddr);

        // Perform the attack: attacker calls Collect which re-enters Put via receive
        vm.prank(attackerAddr);
        attacker.attack{value: 0}();

        // After attack, get attacker's balance
        (, uint balanceAfter) = c.Acc(attackerAddr);

        // Invariant: attacker's balance should be >= initialDeposit - collectAmount
        // In correct version, balance = initialDeposit - collectAmount (the Put in receive fails due to lock)
        // In buggy version, re-entrant Put succeeds, inflating balance before subtraction,
        // so balanceAfter > initialDeposit - collectAmount (more Ether remains, invariant broken)
        assertTrue(balanceAfter >= balanceBefore - collectAmount);
    }
}
