pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant log = address(0x1);
    function setUp() public { c = new C(log); }
    function testFuzz_property(uint256 depositAmount, uint256 reentrantAmount) public {
        // Bound amounts to reasonable ranges to avoid overflows and ensure it's above MinSum
        vm.assume(depositAmount >= 1 ether && depositAmount <= 100 ether);
        vm.assume(reentrantAmount >= 1 ether && reentrantAmount <= 10 ether);

        // Deploy attacker that re-enters on collect
        Attacker attacker = new Attacker(c);

        // Give attacker ether for initial deposit
        vm.deal(address(attacker), depositAmount + reentrantAmount);

        // Attacker makes initial deposit to set up balance and unlock time
        vm.prank(address(attacker));
        c.Put{value: depositAmount}(0); // unlockTime = block.timestamp

        // Warp past unlock time
        vm.warp(block.timestamp + 1);

        // Record balance before collect+re-entrant Put
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(attacker));

        // Attacker initiates collect, which will trigger re-entrant Put via receive
        vm.prank(address(attacker));
        attacker.attack(reentrantAmount);

        // After transaction, the balance should be balanceBefore - reentrantAmount + reentrantAmount = balanceBefore
        // But in the buggy version, re-entrant Put during collect adds reentrantAmount to balance
        // while sub_uint256 subtracts from a possibly stale or manipulated balance
        (, uint balanceAfter) = c.Acc(address(attacker));

        // The invariant: after a sequence that deposits depositAmount initially and then
        // collects reentrantAmount while re-entering with another Put of reentrantAmount,
        // the final balance should be exactly depositAmount (original deposit + reentrant deposit - collect amount)
        // Reference: depositAmount initial, then reentrant Put adds reentrantAmount, then collect subtracts reentrantAmount
        // Result: depositAmount + reentrantAmount - reentrantAmount = depositAmount
        // Buggy: reentrancy lock fails, so collect reads inflated balance, subtracts, then reentrant Put adds again, causing double addition
        assertTrue(balanceAfter == depositAmount);
    }
}

contract Attacker {
    C target;
    bool attacking;
    uint256 reentrantValue;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 _reentrantValue) external payable {
        reentrantValue = _reentrantValue;
        attacking = true;
        target.Collect(reentrantValue);
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // Re-enter Put with additional ether
            target.Put{value: reentrantValue}(0);
        }
    }
}

