import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount, uint256 unlock) public {
        // restrict amount to admissible range: non-zero and not exceeding a reasonable cap to allow multiple calls
        vm.assume(amount > 0 && amount < 100 ether);
        // unlock time can be any value, but we bound to prevent overflow issues
        unlock = bound(unlock, block.timestamp, block.timestamp + 365 days);

        // adversarial re-entrant attacker: in its receive(), calls back into c.Put(0)
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), amount);

        // record balance before
        (uint balBeforeRecipient,) = c.Acc(address(attacker));

        // attacker performs one Put with Ether
        vm.prank(address(attacker));
        c.Put{value: amount}(unlock);

        // after Put, the attacker's balance must equal the Ether they sent
        (uint balAfterRecipient,) = c.Acc(address(attacker));
