        try c.Put{value: amount2}(unlockTime) {
            // If Put succeeds, warp past unlockTime and try Collect
        } catch {
            // Buggy contract reverts second Put; skip assertion for this path
            return;
        }

        // Warp past unlockTime
        vm.warp(unlockTime + 1);

        // Collect from sender2 should succeed (balance >= MinSum and unlocked and balance >= amount)
        uint256 minSum = c.MinSum();
